#!/system/bin/sh
# Generated by MOGA Bridge. Starts or stops the virtual-gamepad helper.
#
#   sh helper.sh          start (default)
#   sh helper.sh stop     stop
#   sh helper.sh status   print whether it is running
#
# The helper listens only on the phone's loopback (127.0.0.1) and runs Android's own
# `uinput` tool as the adb shell user. Every connection must first send the secret stored in
# helper.token (readable only through this app's private storage); any other connection is
# dropped before it can create an input device.

DIR="@DIR@"
PORT="@PORT@"
PATTERN="nc -s 127.0.0.1 -p $PORT"

running_pids() {
  ps -A -o PID,ARGS | grep -F "$PATTERN" | grep -v grep | while read -r pid rest; do
    echo "$pid"
  done
}

case "${1:-start}" in
  stop)
    pids="$(running_pids)"
    if [ -z "$pids" ]; then echo "not running"; else kill $pids && echo "stopped"; fi
    ;;
  status)
    if [ -n "$(running_pids)" ]; then echo "running"; else echo "not running"; exit 1; fi
    ;;
  start)
    if [ ! -r "$DIR/helper.token" ]; then
      echo "Missing $DIR/helper.token: open MOGA Bridge once and try again." >&2
      exit 1
    fi
    if [ -n "$(running_pids)" ]; then echo "already running"; exit 0; fi
    setsid nohup toybox nc -s 127.0.0.1 -p "$PORT" -L sh -c \
      'read -r -t 5 t || exit 1; [ "$t" = "$(cat "'"$DIR"'/helper.token")" ] || exit 1; exec uinput -' \
      >/dev/null 2>&1 </dev/null &
    sleep 1
    if [ -n "$(running_pids)" ]; then echo "started"; else echo "could not start" >&2; exit 1; fi
    ;;
  *)
    echo "usage: sh helper.sh [start|stop|status]" >&2
    exit 2
    ;;
esac
